//! kernel32.dll / kernelbase.dll / `api-ms-win-core-*` API sets.
//!
//! The export table is generated by `build.rs` from every top-level
//! `pub extern "win64" fn` in this directory plus [`crate::sync`] and
//! [`crate::unwind`] (Rtl* functions that kernel32 forwards to ntdll).

pub mod file;
pub mod memory;
pub mod module;
pub mod process;
pub mod string;
pub mod sysinfo;
pub mod threadpool;
pub mod threads;
pub mod time;

pub static EXPORTS: &[crate::Export] = include!(concat!(env!("OUT_DIR"), "/kernel32_exports.rs"));
